    position: relative;
    display: inline-flex;
}

.property-selector__trigger {
    display: inline-flex;
    align-items: center;
    gap: 10px;
    border: 1px solid rgba(255, 255, 255, 0.14);
    background: rgba(0, 0, 0, 0.2);
    color: #f0f0f0;
    padding: 6px 12px 6px 10px;
    border-radius: 10px;
    font-family: system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Arial, sans-serif;
    cursor: pointer;
    max-width: 320px;
    transition: border-color 0.2s ease, background 0.2s ease;
}

.property-selector__trigger:hover {
    border-color: rgba(192, 159, 83, 0.35);
    background: rgba(192, 159, 83, 0.08);
}

.property-selector__mode-icon {
    width: 26px;
    height: 26px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 6px;
    background: rgba(192, 159, 83, 0.18);
}

.property-selector__mode-icon img {
    width: 16px;
    height: 16px;
    filter: brightness(0) saturate(100%) invert(78%) sepia(24%) saturate(500%) hue-rotate(357deg) brightness(95%);
}

.property-selector__trigger-text {
    display: flex;
    flex-direction: column;
    min-width: 0;
    text-align: left;
    line-height: 1.25;
}

.property-selector__trigger-context {
    font-size: 0.625rem;
    font-weight: 600;
    letter-spacing: 0.02em;
    text-transform: uppercase;
    color: rgba(255, 255, 255, 0.5);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.property-selector__trigger-domain {
    font-size: 0.8125rem;
    font-weight: 600;
    color: #f0f0f0;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.property-selector__caret {
    width: 7px;
    height: 7px;
    flex-shrink: 0;
    border-right: 2px solid rgba(255, 255, 255, 0.45);
    border-bottom: 2px solid rgba(255, 255, 255, 0.45);
    transform: rotate(45deg) translateY(-2px);
}

.property-selector__panel {
    position: absolute;
    top: calc(100% + 8px);
    left: 0;
    z-index: 220;
    width: min(640px, calc(100vw - 24px));
    display: flex;
    flex-direction: column;
    overflow: hidden;
    background: linear-gradient(168deg, rgba(52, 52, 56, 0.98) 0%, rgba(32, 32, 36, 0.99) 100%);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 12px;
    box-shadow: 0 20px 48px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.06);
}

.property-selector__mode-row {
    display: flex;
    gap: 6px;
    padding: 10px 12px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.property-selector__mode-btn {
    display: flex;
    align-items: center;
    gap: 8px;
    padding: 6px 12px;
    border: 1px solid transparent;
    border-radius: 8px;
    background: transparent;
    color: rgba(255, 255, 255, 0.65);
    font-size: 0.75rem;
    font-weight: 600;
    cursor: pointer;
    transition: background 0.15s ease, color 0.15s ease, border-color 0.15s ease;
}

.property-selector__mode-btn img {
    width: 16px;
    height: 16px;
    filter: brightness(0) invert(1) opacity(0.65);
}

.property-selector__mode-btn:hover {
    background: rgba(255, 255, 255, 0.06);
    color: #fff;
}

.property-selector__mode-btn--active {
    background: rgba(192, 159, 83, 0.16);
    border-color: rgba(192, 159, 83, 0.4);
    color: #f0f0f0;
}

.property-selector__mode-btn--active img {
    filter: brightness(0) saturate(100%) invert(78%) sepia(24%) saturate(500%) hue-rotate(357deg) brightness(95%);
}

.property-selector__org-row {
    position: relative;
    padding: 8px 12px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.property-selector__org-btn {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    border: none;
    background: transparent;
    color: #f0f0f0;
    font-size: 0.8125rem;
    font-weight: 600;
    padding: 4px 2px;
    cursor: pointer;
    text-align: left;
}

.property-selector__org-badge {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 18px;
    height: 18px;
    border-radius: 50%;
    background: #d0463c;
    color: #fff;
    font-size: 0.6875rem;
    font-weight: 700;
    flex-shrink: 0;
}

.property-selector__org-name {
    flex: 1;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.property-selector__org-list {
    position: absolute;
    top: calc(100% + 2px);
    left: 12px;
    right: 12px;
    margin: 0;
    padding: 4px 0;
    list-style: none;
    background: rgba(24, 24, 26, 0.98);
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 8px;
    box-shadow: 0 12px 30px rgba(0, 0, 0, 0.5);
    max-height: 220px;
    overflow-y: auto;
    z-index: 5;
}

.property-selector__org-list button {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    border: none;
    background: transparent;
    color: #e4e4e4;
    font-size: 0.8125rem;
    padding: 8px 12px;
    cursor: pointer;
    text-align: left;
}

.property-selector__org-list button:hover {
    background: rgba(192, 159, 83, 0.14);
    color: #fff;
}

.property-selector__org-list img {
    width: 20px;
    height: 20px;
    border-radius: 4px;
    object-fit: contain;
}

.property-selector__search-row {
    padding: 10px 12px 8px;
    border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    background: rgba(0, 0, 0, 0.15);
}

.property-selector__search {
    width: 100%;
    box-sizing: border-box;
    padding: 8px 10px;
    border: 1px solid rgba(255, 255, 255, 0.12);
    border-radius: 8px;
    background: rgba(0, 0, 0, 0.25);
    color: #f0f0f0;
    font-size: 0.8125rem;
    font-family: inherit;
}

.property-selector__search::placeholder {
    color: rgba(255, 255, 255, 0.35);
}

.property-selector__search:focus {
    outline: none;
    border-color: rgba(192, 159, 83, 0.45);
    box-shadow: 0 0 0 2px rgba(192, 159, 83, 0.15);
}

.property-selector__tabs {
    display: flex;
    gap: 4px;
    padding: 8px 12px 0;
}

.property-selector__tab {
    border: none;
    background: transparent;
    color: rgba(255, 255, 255, 0.55);
    font-size: 0.75rem;
    font-weight: 600;
    padding: 6px 10px;
    border-bottom: 2px solid transparent;
    cursor: pointer;
}

.property-selector__tab:hover {
    color: #fff;
}

.property-selector__tab--active {
    color: #c0a053;
    border-bottom-color: #c0a053;
}

.property-selector__columns {
    display: grid;
    grid-template-columns: 200px 1fr;
    height: min(60vh, 380px);
    overflow: hidden;
}

