    padding: 10px 14px 6px;
    font-size: 0.6875rem;
    font-weight: 700;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: rgba(192, 159, 83, 0.85);
    flex-shrink: 0;
}

.property-selector__list {
    margin: 0;
    padding: 0 6px 8px;
    list-style: none;
    overflow-y: auto;
    flex: 1;
}

.property-selector__row {
    display: flex;
    align-items: center;
    gap: 8px;
    width: 100%;
    border: none;
    background: transparent;
    color: #e4e4e4;
    font-size: 0.8125rem;
    padding: 8px 8px;
    border-radius: 8px;
    cursor: pointer;
    text-align: left;
    transition: background 0.15s ease, color 0.15s ease;
}

.property-selector__row:hover {
    background: rgba(192, 159, 83, 0.14);
    color: #fff;
}

.property-selector__row--active {
    background: rgba(192, 159, 83, 0.2);
    color: #fff;
}

.property-selector__ws-icon {
    width: 22px;
    height: 22px;
    flex-shrink: 0;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: 6px;
    background: rgba(192, 159, 83, 0.2);
    border: 1px solid rgba(192, 159, 83, 0.35);
    color: #c0a053;
    font-size: 0.6875rem;
    font-weight: 700;
}

.property-selector__ws-icon--all {
    background: rgba(255, 255, 255, 0.08);
    border-color: rgba(255, 255, 255, 0.16);
    color: rgba(255, 255, 255, 0.8);
}

.property-selector__row-text {
    display: flex;
    flex-direction: column;
    gap: 1px;
    min-width: 0;
}

.property-selector__row-name {
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.property-selector__row-name--mono {
    font-family: ui-monospace, SFMono-Regular, "SF Mono", Menlo, Consolas, monospace;
    flex: 1;
}

.property-selector__row-sub {
    font-size: 0.6875rem;
    color: rgba(192, 159, 83, 0.85);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
}

.property-selector__row--domain {
    justify-content: flex-start;
}

.property-selector__check {
    color: #7dd590;
    font-size: 0.75rem;
    flex-shrink: 0;
}

.property-selector__favicon {
    width: 18px;
    height: 18px;
    border-radius: 4px;
    object-fit: contain;
    flex-shrink: 0;
}

.property-selector__verify {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 16px;
    height: 16px;
    border-radius: 50%;
    font-size: 0.5625rem;
    font-weight: 700;
    flex-shrink: 0;
}

.property-selector__verify--verified {
    background: rgba(80, 180, 100, 0.2);
    border: 1px solid rgba(80, 180, 100, 0.4);
    color: #7dd590;
}

.property-selector__verify--unverified {
    background: rgba(220, 160, 60, 0.2);
    border: 1px solid rgba(220, 160, 60, 0.4);
    color: #e8c76a;
}

.property-selector__verify--expired {
    background: rgba(220, 100, 80, 0.2);
    border: 1px solid rgba(220, 100, 80, 0.4);
    color: #f0a8a0;
}

.property-selector__primary-tag {
    font-size: 0.5625rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    padding: 2px 5px;
    border-radius: 3px;
    background: rgba(192, 159, 83, 0.2);
    border: 1px solid rgba(192, 159, 83, 0.35);
    color: #c0a053;
    flex-shrink: 0;
}

.property-selector__star {
    margin-left: auto;
    border: none;
    background: transparent;
    color: rgba(255, 255, 255, 0.3);
    font-size: 0.9rem;
    line-height: 1;
    cursor: pointer;
    padding: 2px;
    flex-shrink: 0;
}

.property-selector__star:hover {
    color: rgba(192, 159, 83, 0.8);
}

.property-selector__star--active {
    color: #c0a053;
}

.property-selector__empty {
    padding: 14px 12px;
    font-size: 0.75rem;
    color: rgba(255, 255, 255, 0.4);
    text-align: center;
}

@media screen and (min-width: 320px) and (max-width: 900px) {
    .property-selector {
        width: 100%;
    }

    .property-selector__trigger {
        width: 100%;
        max-width: none;
    }

    .property-selector__panel {
        left: 0;
        right: 0;
        width: 100%;
    }

    .property-selector__columns {
        grid-template-columns: 1fr;
        grid-auto-rows: min-content;
        max-height: min(70vh, 480px);
        overflow-y: auto;
    }

    .property-selector__col {
        border-right: none;
        border-bottom: 1px solid rgba(255, 255, 255, 0.08);
    }
}
